<?php declare(strict_types=1);
use Kulturhus\Verein\MemberBankVault;
use Kulturhus\Native\Integration\MemberBankAuthentication;
use Kulturhus\Native\Shared\Db;
/** Existing native accounts and encrypted originals, through the real departure action. */
(function()use($db,$root,$contact,$registry,$auth,$fourthToken,$check,$deny,$run,&$token):void{
    $cfg=\Kulturhus\Native\TestSupport::config();if(($cfg['owner']??'')!=='isolated-native-ci'||($cfg['label']??'')!=='native-member-bank')throw new RuntimeException('Owned native bank date fixture required.');
    require_once __DIR__.'/original-database-hash.php';
    $zone=date_default_timezone_get();$keyHash=hash_file('sha256',$root.'/bank.key');$oldHistory=$db->query('SELECT * FROM member_bank_history ORDER BY operation_id')->fetchAll();
    $owner=new MemberBankVault($db,'bank-member',$root.'/bank.key',1,static fn()=>MemberBankAuthentication::identity($db,'bank-member',$auth,$fourthToken));$admin=new MemberBankVault($db,'bank-admin',$root.'/bank.key');
    Db::run($db,"INSERT INTO member_bank_config(club_id,sepa_enabled,creditor_id,creditor_name,creditor_address) VALUES('bank-club',1,'DE98ZZZ09999999999','Own dated bank creditor','Own address 1')");
    $state=$owner->summary($contact);$terms=$owner->mandateTerms($contact)['payload'];$grant=bin2hex(random_bytes(32));$session=hash('sha256','own-date-contract-session');
    Db::run($db,'INSERT INTO member_bank_grants(token_hash,club_id,actor_id,contact_id,action,expected_version,payload_hash,session_hash,expires_at) VALUES(?,?,?,?,?,?,?,?,?)',[hash('sha256',$grant),'bank-club','bank-member',$contact,'mandate',$state['version'],MemberBankVault::payloadHash('mandate',$terms),$session,time()+60]);
    $mandated=$owner->mandate($contact,$state['version'],$terms,$grant,$session);$originalMandate=$admin->mandateForCollection($contact);$bank=$admin->currentBankForReimbursement($contact);$check($mandated['status']==='mandated'&&$originalMandate['reference']===$mandated['mandate_ref'],'dated test starts with an actual encrypted and explicitly granted mandate');
    $today=(new DateTimeImmutable('now',new DateTimeZone('Europe/Berlin')))->format('Y-m-d');$future=(new DateTimeImmutable($today))->modify('+30 days')->format('Y-m-d');$yesterday=(new DateTimeImmutable($today))->modify('-1 day')->format('Y-m-d');$tomorrow=(new DateTimeImmutable($today))->modify('+1 day')->format('Y-m-d');
    $membership=Db::run($db,'SELECT * FROM memberships WHERE club_id=? AND contact_id=?',['bank-club',$contact])->fetch();$registry->endMembership($membership['id'],(int)$membership['version'],$future);
    $check(Db::run($db,'SELECT status FROM memberships WHERE club_id=? AND id=?',['bank-club',$membership['id']])->fetchColumn()==='ehemalig','real departure action records former status immediately even for a future end');
    $tables=$db->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN);$protected=array_values(array_diff($tables,['native_auth_sessions','native_auth_limits']));$before=ownOriginalDatabaseHash($db,$protected);
    $check((new \Kulturhus\Verein\WorkspaceAccess($db,'bank-member'))->allows(['view'=>'portal','tab'=>'bank']),'future actual departure does not hide the own bank menu');
    $check($owner->summary($contact)['mandate_ref']===$originalMandate['reference'],'future departure preserves the original own mandate summary');
    $check($admin->mandateForCollection($contact)===$originalMandate,'future departure preserves the exact current collection mandate');$check($admin->currentBankForReimbursement($contact)===$bank,'future departure preserves the exact authorized reimbursement bank source');$check(count($admin->availableMembers())===1,'future departure remains selectable by the authorized bank administrator');
    $token=$fourthToken;$controller=$run();$check($controller['error']===''&&!$controller['private_html']&&!$controller['session_plain'],'actual native controller still offers the masked bank page after future departure');
    $check($before===ownOriginalDatabaseHash($db,$protected),'all future-departure reads preserve every whole original outside authentication metadata');
    try{
        $instant=new DateTimeImmutable('now');$opposite=null;foreach(['Pacific/Kiritimati','Etc/GMT+12']as$candidate)if($instant->setTimezone(new DateTimeZone($candidate))->format('Y-m-d')!==$today){$opposite=$candidate;break;}$check($opposite!==null,'owned test selects a real server timezone on a different calendar day');date_default_timezone_set($opposite);
        Db::run($db,'UPDATE memberships SET ends_on=?,version=version+1 WHERE club_id=? AND id=?',[$today,'bank-club',$membership['id']]);$before=ownOriginalDatabaseHash($db,$protected);
        $check(date('Y-m-d')!==$today,'server default day genuinely differs from the Berlin membership end day');
        $check((new \Kulturhus\Verein\WorkspaceAccess($db,'bank-member'))->allows(['view'=>'portal','tab'=>'bank'])&&$owner->summary($contact)['mandate_ref']===$originalMandate['reference'],'own bank menu and vault include the complete actual Berlin end day');
        $check($admin->mandateForCollection($contact)===$originalMandate&&$admin->currentBankForReimbursement($contact)===$bank&&count($admin->availableMembers())===1,'collection reimbursement and selection share the same Berlin end-day contract');
        $check($before===ownOriginalDatabaseHash($db,$protected),'server-timezone boundary checks preserve every whole original');
        Db::run($db,'UPDATE memberships SET ends_on=?,version=version+1 WHERE club_id=? AND id=?',[$yesterday,'bank-club',$membership['id']]);$before=ownOriginalDatabaseHash($db,$protected);
        $check(!(new \Kulturhus\Verein\WorkspaceAccess($db,'bank-member'))->allows(['view'=>'portal','tab'=>'bank']),'personal bank menu ends after the actual final Berlin day');$deny(fn()=>$owner->summary($contact),'actual former member cannot read the personal vault');$deny(fn()=>$admin->mandateForCollection($contact),'membership-dependent collection source stays blocked after the actual end');$deny(fn()=>$admin->currentBankForReimbursement($contact),'membership-dependent reimbursement source stays blocked after the actual end');$check($admin->availableMembers()===[],'ended membership is absent from current bank selection');$check($before===ownOriginalDatabaseHash($db,$protected),'expired membership refusals consume and change no bank or financial original');
        Db::run($db,'UPDATE memberships SET starts_on=?,ends_on=?,version=version+1 WHERE club_id=? AND id=?',[$tomorrow,$future,'bank-club',$membership['id']]);$before=ownOriginalDatabaseHash($db,$protected);
        $check(!(new \Kulturhus\Verein\WorkspaceAccess($db,'bank-member'))->allows(['view'=>'portal','tab'=>'bank']),'future membership start does not expose the personal bank menu');$deny(fn()=>$owner->summary($contact),'future member cannot read the personal vault before joining');$deny(fn()=>$admin->mandateForCollection($contact),'future start cannot prepare a current member mandate');$check($before===ownOriginalDatabaseHash($db,$protected),'future-start refusals retain every complete original');
        Db::run($db,'UPDATE memberships SET starts_on=?,version=version+1 WHERE club_id=? AND id=?',[$membership['starts_on'],'bank-club',$membership['id']]);Db::run($db,"UPDATE contacts SET archived_at='2020-01-01T00:00:00Z' WHERE club_id='bank-club' AND id=?",[$contact]);$before=ownOriginalDatabaseHash($db,$protected);
        $deny(fn()=>$owner->summary($contact),'archived person remains excluded despite a future end');$deny(fn()=>$admin->mandateForCollection($contact),'archived person cannot become a current collection source');$check($before===ownOriginalDatabaseHash($db,$protected),'archived-source refusals preserve bank and financial originals');
    }finally{date_default_timezone_set($zone);}
    foreach($oldHistory as$row){$q=Db::run($db,'SELECT * FROM member_bank_history WHERE operation_id=?',[$row['operation_id']]);$check($q->fetch()===$row,'earlier encrypted bank-history original remains byte-exact');}$check(hash_file('sha256',$root.'/bank.key')===$keyHash,'dated membership access never replaces the private bank key');
})();
